# generated, and runnable as-is
from publishable import BaseStep, Estimate


class Step(BaseStep):
    scope = "summary"

    def run(self, cfg, io):
        return {{"headline": Estimate(value=0.5, ci95=[0.4, 0.6], n=12,
                                      method="hand_computed")}}
